#define DMX_GRAPH_NO_MAIN
#include "dmx_graph.cpp"
#include "film_scene_render_binding_candidate.h"
#include <iostream>
#include <algorithm>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(argc!=2)throw std::runtime_error("session required");auto graph=loadGraph(argv[1]);size_t shots=0;for(uint32_t id=0;id<graph.elements.size();++id){auto&e=graph.elements[id];if(graph.strings.at(e.type)!="DmeFilmClip")continue;if(hierarchyRefs(graph,e,"camera",1).empty())continue;auto binding=readFilmSceneRenderBindingCandidate(graph,id);std::cout<<"shot="<<id<<" camera="<<binding.camera<<" scene="<<binding.scene<<" models="<<binding.models.size()<<'\n';++shots;}auto first=readFilmSceneRenderBindingCandidate(graph,2470);if(first.camera!=2481||std::find(first.models.begin(),first.models.end(),uint32_t(2552))==first.models.end())throw std::runtime_error("Mamagen shot binding");size_t rejected=0;try{readFilmSceneRenderBindingCandidate(graph,2237);}catch(const std::runtime_error&){++rejected;}auto&scene=graph.elements[first.scene];auto child=namedAttribute(graph,scene,"children");if(!child)throw std::runtime_error("scene children fixture");auto changed=*child;changed.values.clear();Value self;self.reference=first.scene;changed.values.push_back(self);for(auto&a:scene.attributes)if(a.name==child->name){auto saved=a;a=changed;try{readFilmSceneRenderBindingCandidate(graph,2470);}catch(const std::runtime_error&){++rejected;}a=std::move(saved);break;}if(shots!=27||rejected!=2)throw std::runtime_error("binding checks");std::cout<<"x64 film scene bindings passed shots="<<shots<<" rejected="<<rejected<<" graph_modified=no\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
